/* Pixel Paddock 04. Original game screens; source dates remain part of the product. */
(()=>{'use strict';
const $=(s,root=document)=>root.querySelector(s),$$=(s,root=document)=>[...root.querySelectorAll(s)],main=$('#main');
const read=(k,d)=>{try{return JSON.parse(localStorage.getItem('paddock:'+k))??d}catch{return d}};
const state={data:null,selectedDriver:'antonelli',search:'',team:'',newsEntity:'',table:'drivers',session:'race',fullStandings:false,favorites:read('favorites',[]),notes:read('notes',[]),motion:read('motion',true),paddockTab:'news'};
if(!Array.isArray(state.favorites))state.favorites=[];if(!Array.isArray(state.notes))state.notes=[];
const save=(k,v)=>{try{localStorage.setItem('paddock:'+k,JSON.stringify(v))}catch{toast('Browser storage is unavailable. Saved for this visit.')}};
const esc=(v='')=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const url=v=>{try{const u=new URL(v);return /^https?:$/.test(u.protocol)?u.href:''}catch{return ''}};
const col=v=>/^#[a-f\d]{6}$/i.test(v||'')?v:'#8ea2b5';
const ext=(u,label,cls='text-link')=>url(u)?`<a class="${cls}" href="${esc(url(u))}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:'';
const n=v=>v==null?'—':Number(v).toLocaleString('en-GB');
const date=(v,full=false)=>{if(!v)return 'Not supplied';const d=new Date(v);return isNaN(d)?'Not supplied':d.toLocaleDateString('en-GB',{day:'numeric',month:full?'long':'short',...(full?{year:'numeric'}:{}),timeZone:'UTC'})};
const time=v=>v&&!isNaN(new Date(v))?new Date(v).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:'UTC'})+' UTC':'Time TBC';
const allDrivers=()=>[...state.data.drivers,...(state.data.formerDrivers||[])];
const find=(kind,id)=>(kind==='driver'?allDrivers():state.data[kind==='team'?'teams':'principals']).find(x=>x.id===id);
const teamOf=x=>find('team',x?.teamId||x?.id);
const path=(kind,id)=>`#/${kind}/${encodeURIComponent(id)}`;
const standing=(kind,id)=>state.data.standings[kind==='team'?'teams':'drivers'].find(x=>(x.driverId||x.teamId)===id);
const route=()=>{const [route,q='']=location.hash.replace(/^#\/?/,'').split('?'),[page='dashboard',raw='']=route.split('/');let id='';try{id=decodeURIComponent(raw)}catch{}return {page:page||'dashboard',id,params:new URLSearchParams(q)}};
const teamCode=t=>({red_bull:'RBR',aston_martin:'AMR',mercedes:'MER',mclaren:'MCL',ferrari:'FER',rb:'VCARB',haas:'HAAS',alpine:'ALP',audi:'AUD',williams:'WIL',cadillac:'CAD'}[t?.id]||'F1');
const age=x=>{if(!x.dateOfBirth)return null;const now=new Date(state.data.meta.updatedAt),d=new Date(x.dateOfBirth);return now.getUTCFullYear()-d.getUTCFullYear()-((now.getUTCMonth()<d.getUTCMonth()||(now.getUTCMonth()===d.getUTCMonth()&&now.getUTCDate()<d.getUTCDate()))?1:0)};
function toast(t){const el=$('#toast');el.textContent=t;el.classList.add('visible');clearTimeout(el._timer);el._timer=setTimeout(()=>el.classList.remove('visible'),3800)}
function stamp(section,compact=false){const x=state.data.meta.sectionFreshness?.[section];if(!x)return '';return `<div class="source-stamp${compact?' compact':''}"><span class="tiny-pixel"></span><span>${esc(x.session||'Source checked')} <span class="stamp-date">· ${date(x.fetchedAt)} ${time(x.fetchedAt)}</span></span>${compact?'':ext(x.sourceUrls?.[0],'Source')}</div>`}
function heading(kicker,title,description='',extra=''){return `<div class="screen-heading"><div><p class="eyebrow">${esc(kicker)}</p><h1>${title}</h1>${description?`<p class="screen-description">${esc(description)}</p>`:''}</div>${extra}</div>`}
function empty(title,copy){return `<div class="empty-state"><span aria-hidden="true">[ — ]</span><h3>${esc(title)}</h3><p>${esc(copy)}</p></div>`}
function tabButton(label,key,active,attribute='data-table'){return `<button class="tab ${active?'active':''}" ${attribute}="${esc(key)}" aria-pressed="${active}">${esc(label)}</button>`}
function sectionHead(kicker,title,link=''){return `<div class="panel-heading"><div><span class="section-kicker">${esc(kicker)}</span><h2>${esc(title)}</h2></div>${link}</div>`}
function fav(kind,item,large=false){const key=kind+':'+item.id,on=state.favorites.includes(key);return `<button class="${large?'button secondary':'save-button'}${on?' saved':''}" data-favorite="${esc(key)}" aria-pressed="${on}" aria-label="${on?'Unsave':'Save'} ${esc(item.name)}">${on?'♥':'♡'}${large?on?' SAVED':' SAVE TO MY GRID':''}</button>`}
function sprite(item,kind='driver',mode='full'){const art=window.PADDOCK_ART?.people?.[item.id],c=col(teamOf(item)?.color);if(art)return `<span class="character ${mode}" style="--team:${c}"><span class="sprite-sheet" role="img" aria-label="Original pixel illustration of ${esc(item.name)}" data-person="${esc(item.id)}" style="--sheet:url('${esc(art.src)}');--row:${art.row*50}%;--frames:${art.frames||6}"></span></span>`;return `<span class="character ${mode} fallback-art" data-person="${esc(item.id)}" style="--team:${c}">${window.PixelPaddockArt.person(item,kind,c)}</span>`}
function playButton(item){return `<button class="button play-button" data-play="${esc(item.id)}"><span aria-hidden="true">▶</span> ${esc(item.animation?.label||'Play signature')}</button>`}
function car(t){return `<div class="car-render" style="--team:${col(t.color)}">${window.PixelPaddockArt.car(t)}</div>`}
function teamBadge(t,compact=false){return `<span class="team-badge${compact?' small':''}" style="--team:${col(t?.color)}">${esc(teamCode(t))}</span>`}
function driverLink(d,small=false){if(!d)return '<span>Unmatched entry</span>';const t=teamOf(d);return `<a class="driver-link${small?' small':''}" href="${path('driver',d.id)}"><i style="background:${col(t?.color)}"></i>${sprite(d,'driver','mini')}<span><strong>${esc(d.name)}</strong><small>${esc(t?.name||'Season entrant')}${d.currentGrid===false?' · SEASON ENTRANT':''}</small></span><b class="driver-code">${esc(d.code)}</b></a>`}
function stats(items){return `<div class="stat-grid">${items.map(([v,l])=>`<div class="stat"><strong>${esc(v)}</strong><span>${esc(l)}</span></div>`).join('')}</div>`}
function standingsTable(kind=state.table,limit=state.fullStandings?99:6){const rows=state.data.standings[kind].slice(0,limit),leader=Number(rows[0]?.points)||1;return `<div class="table-scroll"><table class="timing-table"><caption class="sr-only">${kind==='drivers'?'Driver':'Constructor'} championship after the Singapore Grand Prix</caption><thead><tr><th>POS</th><th>${kind==='drivers'?'DRIVER / TEAM':'CONSTRUCTOR'}</th><th class="desktop-cell">WINS</th><th class="score">PTS</th></tr></thead><tbody>${rows.map(r=>{const entity=find(kind==='drivers'?'driver':'team',r.driverId||r.teamId),t=kind==='drivers'?teamOf(entity):entity;return `<tr><td class="position ${r.position<=3?'podium':''}">${String(r.position).padStart(2,'0')}</td><td>${kind==='drivers'?driverLink(entity):`<a class="constructor-link" href="${path('team',entity.id)}">${teamBadge(entity,true)}<strong>${esc(entity.name)}</strong></a>`}</td><td class="desktop-cell wins">${n(r.wins)}</td><td class="score"><b>${n(r.points)}</b><span class="score-bar" style="--bar:${Math.max(1,r.points/leader*100)}%;--team:${col(t?.color)}"></span></td></tr>`}).join('')}</tbody></table></div>`}
function countdown(){return `<div class="countdown" data-countdown="${esc(state.data.currentWeekend.raceStart)}"><span><b data-unit="d">--</b><small>DAYS</small></span><i>:</i><span><b data-unit="h">--</b><small>HRS</small></span><i>:</i><span><b data-unit="m">--</b><small>MIN</small></span><i>:</i><span><b data-unit="s">--</b><small>SEC</small></span></div>`}
function sessions(compact=false){return `<ol class="session-list${compact?' compact':''}">${state.data.currentWeekend.sessions.map((s,i)=>`<li class="${s.status==='upcoming'?'next':''}"><span class="session-index">${String(i+1).padStart(2,'0')}</span><div><strong>${esc(s.type)}</strong><small>${date(s.date)} · ${esc(s.time.slice(0,5))} UTC${s.note?' · DELAYED START':''}</small></div><span class="session-status">${s.status==='completed'?'DONE':'NEXT'}</span></li>`).join('')}</ol>`}
function raceHero(){const w=state.data.currentWeekend;return `<section class="race-hero" style="--scene:url('${esc(window.PADDOCK_ART.scene)}')"><div class="hero-text"><div class="hero-overline"><span class="red-lights"><i></i><i></i><i></i><i></i><i></i></span> ROUND ${String(w.round).padStart(2,'0')} / ${state.data.calendar.length}</div><span class="pixel-tag">CHEQUERED FLAG</span><h1>SINGAPORE<br><em>AFTER DARK.</em></h1><p>Under the lights. On the limit.<br>The race story. The championship picture.</p><a class="button primary" href="#/race/singapore">ENTER RACE CENTRE <span>→</span></a></div><div class="hero-corner" aria-hidden="true"><span>MARINA BAY</span><span>1.29° N / 103.86° E</span></div><div class="race-hud"><div><span class="hud-label">RACE WINNER / 11 OCT</span><strong>VERSTAPPEN</strong></div><div class="hud-countdown"><span class="hud-label">WINNING TIME / 62 LAPS</span><strong>1:42:00.785</strong></div><a href="#/race/singapore" class="hud-session"><span class="hud-label">THE PODIUM</span><strong>VER / LEC / ANT <span>↗</span></strong><small>FULL RACE CLASSIFICATION</small></a></div></section>`}
function newsCard(item,index=0){const t=(item.tags||[]).map(id=>find('team',id)).find(Boolean),driver=(item.tags||[]).map(id=>find('driver',id)).find(Boolean);return `<article class="news-card" style="--team:${col(t?.color||teamOf(driver)?.color)}"><div class="news-card-top"><span class="news-channel">${esc(item.category||'PADDOCK RADIO')}</span><span>${date(item.publishedAt)}</span></div><h3>${ext(item.url,item.title,'story-link')}</h3><p>${esc(item.summary||'')}</p><div class="news-card-bottom"><div class="tags">${(item.tags||[]).slice(0,2).map(tagLink).join('')}</div><span class="source-name">${esc(item.source)}</span></div></article>`}
function tagLink(id){for(const kind of ['driver','team','principal']){const x=find(kind,id);if(x)return `<a class="tag" href="${path(kind,id)}">${esc(x.code||x.shortName||x.name)}</a>`}return ''}
function home(){return `<div class="screen-topline"><span>01 / RACE CONTROL</span><span class="yellow">2026 WORLD CHAMPIONSHIP</span></div>${raceHero()}<div class="dashboard-grid"><section class="panel championship-panel">${sectionHead('THE TITLE FIGHT','Championship',`<div class="tabs">${tabButton('DRIVERS','drivers',state.table==='drivers')}${tabButton('TEAMS','teams',state.table==='teams')}</div>`)}<div class="panel-context">AFTER SINGAPORE GRAND PRIX <span>11 OCT 2026</span></div><div id="standings-table">${standingsTable()}</div><div class="panel-foot"><button class="text-link" data-expand-standings>${state.fullStandings?'SHOW TOP SIX':'FULL CLASSIFICATION'} ↓</button>${ext(state.data.meta.sectionFreshness.standings.sourceUrls[0],'Official table')}</div></section><aside class="dashboard-side"><section class="panel weekend-panel">${sectionHead('ROUND 17','The weekend',`<a class="text-link" href="#/race/singapore">OPEN ↗</a>`)}${sessions(true)}<div class="weekend-result"><span>RACE WINNER</span><a href="#/driver/max_verstappen"><b>MAX VERSTAPPEN</b><strong>+25 PTS</strong></a></div></section><a class="select-callout" href="#/drivers"><div><span class="section-kicker">${state.data.drivers.length} DRIVERS. ONE GRID.</span><h2>CHOOSE YOUR<br><em>CHARACTER.</em></h2><span class="text-link">ENTER DRIVER SELECT →</span></div><div class="callout-portrait">${sprite(find('driver','hamilton'),'driver','bust')}</div></a></aside></div><section class="news-section">${sectionHead('FRESH FROM THE PIT LANE','Paddock radio','<a class="text-link" href="#/paddock">ALL STORIES ↗</a>')}<div class="news-grid">${state.data.news.slice(0,3).map(newsCard).join('')}</div></section><div class="bottom-status"><span>SNAPSHOT, NOT LIVE TIMING</span>${stamp('standings',true)}</div>`}
function filteredDrivers(){return state.data.drivers.filter(d=>(!state.team||d.teamId===state.team)&&(!state.search||[d.name,d.code,d.number,d.nationality,teamOf(d)?.name].join(' ').toLowerCase().includes(state.search.toLowerCase())))}
function driverSlot(d){const on=state.selectedDriver===d.id,t=teamOf(d);return `<article class="driver-slot ${on?'selected':''}" style="--team:${col(t?.color)}"><button data-select-driver="${esc(d.id)}" aria-pressed="${on}" aria-label="Select ${esc(d.name)}"><span class="slot-number">${esc(d.number)}</span>${sprite(d,'driver','bust')}<span class="slot-name"><small>${esc(d.name.split(' ').slice(0,-1).join(' '))}</small><strong>${esc(d.name.split(' ').at(-1))}</strong></span><i class="slot-team"></i></button><a class="slot-profile" href="${path('driver',d.id)}" aria-label="Open ${esc(d.name)} profile">↗</a></article>`}
function driverPreview(){const d=find('driver',state.selectedDriver)||state.data.drivers[0],t=teamOf(d),s=standing('driver',d.id);return `<div class="selection-stage" style="--team:${col(t?.color)}"><div class="stage-top">PLAYER SELECT <span>${teamBadge(t,true)}</span></div><div class="stage-character"><span class="giant-number" aria-hidden="true">${esc(d.number)}</span>${sprite(d)}<span class="stage-ground"></span><span class="stage-level">${esc(d.code)} / ${esc(d.nationality)}</span></div><div class="selection-name"><small>${esc(d.name.split(' ').slice(0,-1).join(' '))}</small><h2>${esc(d.name.split(' ').at(-1))}</h2><p><i style="background:${col(t?.color)}"></i>${esc(t.name)}</p></div>${stats([[s?'P'+s.position:'—','POSITION'],[s?n(s.points):'—','POINTS'],[s?n(s.wins):'—','GP WINS']])}<div class="selection-actions">${playButton(d)}<a class="button primary" href="${path('driver',d.id)}">DRIVER PROFILE →</a></div></div>`}
function driverPage(){const list=filteredDrivers();if(!list.some(d=>d.id===state.selectedDriver)&&list.length)state.selectedDriver=list[0].id;return `${heading('02 / THE GRID','CHOOSE YOUR <em>DRIVER.</em>','The personalities. The rivalries. The signature moves.','<span class="screen-chip">22 ON THE GRID</span>')}<div class="driver-select-screen"><div id="driver-preview">${driverPreview()}</div><section class="selection-board"><div class="filter-bar"><label class="search-field"><span aria-hidden="true">⌕</span><span class="sr-only">Search drivers</span><input id="search" type="search" value="${esc(state.search)}" placeholder="NAME, NUMBER, COUNTRY…"></label><select id="team-filter" aria-label="Filter by team"><option value="">ALL TEAMS</option>${state.data.teams.map(t=>`<option value="${t.id}" ${state.team===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div><div class="driver-slots" id="driver-slots">${list.length?list.map(driverSlot).join(''):empty('NO DRIVER FOUND','Try another name, number or team.')}</div><div class="selection-hint"><span>← → SELECT DRIVER</span><span>▶ PLAY SIGNATURE</span><span>↗ OPEN PROFILE</span></div></section></div>${stamp('roster')}`}
function teamCard(t,index){const s=standing('team',t.id);return `<article class="garage-card" style="--team:${col(t.color)}"><div class="garage-card-top"><span>GARAGE ${String(index+1).padStart(2,'0')}</span>${fav('team',t)}</div><div class="garage-title">${teamBadge(t)}<div><span>${esc(t.nationality)} CONSTRUCTOR</span><h2><a href="${path('team',t.id)}">${esc(t.name)}</a></h2></div></div><a class="garage-car" href="${path('team',t.id)}" aria-label="Enter ${esc(t.name)} garage">${car(t)}<span class="garage-floor"></span></a><div class="garage-stats"><span><b>P${s?.position||'—'}</b> CHAMPIONSHIP</span><span><b>${n(s?.points)}</b> POINTS</span></div><div class="garage-drivers">${(t.driverIds||[]).map(id=>driverLink(find('driver',id),true)).join('')}</div><a class="garage-enter" href="${path('team',t.id)}">ENTER GARAGE <span>→</span></a></article>`}
function teamsPage(){return `${heading('03 / THE GARAGES','ELEVEN TEAMS.<br><em>ONE CHAMPIONSHIP.</em>','Meet the cars, the drivers and the people calling the shots.')}<div class="garages-grid">${state.data.teams.map(teamCard).join('')}</div>${stamp('standings')}`}
function leaderCard(p){const t=teamOf(p);return `<article class="leader-card" style="--team:${col(t?.color)}"><div class="leader-portrait"><a href="${path('principal',p.id)}" aria-label="Open ${esc(p.name)} profile">${sprite(p,'principal','full')}</a>${fav('principal',p)}<span class="leader-team">${teamBadge(t,true)}</span></div><div class="leader-copy"><span class="section-kicker">${esc(t?.name)}</span><h2><a href="${path('principal',p.id)}">${esc(p.name)}</a></h2><p>${esc(p.role||'Team leadership')}</p><div class="leader-actions"><button class="text-link" data-play="${esc(p.id)}">▶ SIGNATURE</button><a class="text-link" href="${path('principal',p.id)}">PROFILE ↗</a></div></div></article>`}
function leadersPage(){return `${heading('04 / THE PIT WALL','CALLING <em>THE SHOTS.</em>','Team principals, racing directors and the people behind the radio.','<span class="screen-chip">13 PEOPLE / 11 TEAMS</span>')}<div class="leaders-grid">${state.data.principals.map(leaderCard).join('')}</div>${stamp('leadership')}`}
function relatedStories(item){let direct=state.data.news.filter(n=>(n.tags||[]).includes(item.id));if(direct.length)return {list:direct,label:'IN THE HEADLINES'};const team=teamOf(item);return {list:state.data.news.filter(n=>(n.tags||[]).includes(team?.id)),label:'FROM THE '+(team?.name||'PADDOCK').toUpperCase()+' GARAGE'}}
function profile(kind,id){const item=find(kind,id);if(!item)return notFound();const t=kind==='team'?item:teamOf(item),s=kind==='principal'?standing('team',t?.id):standing(kind,id),related=relatedStories(item),comments=state.data.comments.filter(c=>(c.tags||[]).includes(id)),crew=state.data.principals.filter(p=>p.teamId===t?.id),mates=state.data.drivers.filter(d=>d.teamId===t?.id&&d.id!==id),quali=state.data.qualifyingResults.find(r=>r.driverId===id),sprint=state.data.sprintResults.find(r=>r.driverId===id),gp=state.data.results.find(r=>r.driverId===id);
const back=kind==='driver'?'drivers':kind==='team'?'teams':'principals';
return `<a class="back-link" href="#/${back}">← ${kind==='driver'?'DRIVER SELECT':kind==='team'?'ALL GARAGES':'THE PIT WALL'}</a><section class="profile-hero" style="--team:${col(t?.color)}"><div class="profile-copy"><div class="profile-kicker">${teamBadge(t,true)}<span>${kind==='driver'?item.currentGrid===false?'SEASON ENTRANT':`DRIVER #${esc(item.number)}`:kind==='team'?'CONSTRUCTOR FILE':'PIT WALL FILE'}</span></div><h1>${esc(item.name)}</h1><p class="profile-role">${esc(kind==='principal'?item.role:kind==='driver'?item.nationality+' · '+t?.name:t.nationality+' CONSTRUCTOR')}</p><p class="profile-bio">${esc(item.bio)}</p>${stats(kind==='principal'?[[t?.name||'—','TEAM'],[item.nationality||'—','NATIONALITY']]:[[s?'P'+s.position:'—','CHAMPIONSHIP'],[n(s?.points),'POINTS'],[n(s?.wins),'GP WINS']])}<div class="profile-buttons">${fav(kind,item,true)}${ext(item.sourceUrl,'OFFICIAL PROFILE','button secondary')}</div>${kind==='driver'?`<div class="profile-details"><span>BORN <b>${date(item.dateOfBirth,true)}</b></span>${age(item)!==null?`<span>AGE <b>${age(item)}</b></span>`:''}<span>CODE <b>${esc(item.code)}</b></span></div>`:''}</div><div class="profile-stage ${kind==='team'?'team-stage':''}">${kind==='team'?car(item):sprite(item,kind)}<div class="profile-stage-footer">${kind==='team'?'<span>ORIGINAL PIXEL LIVERY</span>':playButton(item)}<small>FAN-ART INTERPRETATION</small></div></div></section><div class="profile-content"><div class="profile-main">${kind==='driver'?`<section class="panel">${sectionHead('SINGAPORE / ROUND 17','This weekend')}<div class="weekend-stats">${quali?`<a href="#/race/singapore"><span>QUALIFYING</span><strong>P${quali.position}</strong><small>${esc(quali.q3||quali.q2||quali.q1||'No time')}</small></a>`:''}${sprint?`<a href="#/race/singapore"><span>SPRINT</span><strong>P${sprint.position}</strong><small>${sprint.points} POINTS</small></a>`:''}<a href="#/race/singapore"><span>GRAND PRIX</span><strong>${gp?gp.position==='NC'?'NC':'P'+gp.position:'—'}</strong><small>${gp?gp.points+' POINTS · '+esc(gp.time):'NOT ENTERED'}</small></a></div><div class="panel-note">Qualifying position is not the final starting grid. Penalties may apply.</div></section>`:''}${kind==='team'?`<section class="profile-roster"><div class="section-title-row"><h2>THE DRIVERS</h2><span>YOUR GARAGE</span></div><div class="team-driver-grid">${mates.map(d=>`<article class="team-driver-card" style="--team:${col(t.color)}">${sprite(d,'driver','bust')}<div><span>#${d.number} / ${esc(d.code)}</span><h3><a href="${path('driver',d.id)}">${esc(d.name)}</a></h3><p>${n(standing('driver',d.id)?.points)} PTS</p></div><a href="${path('driver',d.id)}" aria-label="${esc(d.name)} profile">↗</a></article>`).join('')}</div></section>`:''}<section class="profile-news"><div class="section-title-row"><h2>${esc(related.label)}</h2><a class="text-link" href="#/paddock?entity=${encodeURIComponent(item.id)}">PADDOCK RADIO ↗</a></div><div class="news-grid two">${related.list.length?related.list.map(newsCard).join(''):empty('A QUIET RADIO CHANNEL','No verified story in this snapshot is tagged to this profile. Explore the paddock for the full news wire.')}</div></section>${comments.length?`<section class="profile-comments"><div class="section-title-row"><h2>FAN RADIO</h2></div>${comments.map(commentCard).join('')}</section>`:''}</div><aside class="profile-aside"><section class="panel">${sectionHead('CONNECTIONS','Inside the garage')}<a class="profile-team-link" href="${path('team',t.id)}">${teamBadge(t)}<strong>${esc(t.name)}</strong><span>→</span></a>${kind!=='team'?mates.map(d=>`<div class="roster-link">${driverLink(d,true)}</div>`).join(''):''}${crew.filter(p=>p.id!==id).map(p=>`<a class="crew-link" href="${path('principal',p.id)}">${sprite(p,'principal','mini')}<span><strong>${esc(p.name)}</strong><small>${esc(p.role)}</small></span><b>↗</b></a>`).join('')}</section><section class="profile-source panel"><span class="section-kicker">SOURCE NOTES</span><p>${kind==='principal'?'Leadership roles follow the official 27 August 2026 overview. Distinct executive and racing roles are shown separately.':'Championship figures include the Singapore Grand Prix. This is a dated source snapshot, not live telemetry.'}</p>${stamp(kind==='principal'?'leadership':'standings',true)}${ext(item.sourceUrl,'Profile source')}</section></aside></div>`}
function circuitGraphic(){return `<svg class="circuit-map" viewBox="0 0 400 180" role="img" aria-label="Decorative street-circuit schematic"><defs><pattern id="map-grid" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M20 0H0V20" fill="none" stroke="#34434b" stroke-width="1"/></pattern></defs><rect width="400" height="180" fill="url(#map-grid)"/><path d="M47 109V47h60v25h36V42h74v21h30V41h79v51h-31v48h-62v-28h-45v32h-47v-29H85v22H47Z" fill="none" stroke="#091721" stroke-width="17"/><path d="M47 109V47h60v25h36V42h74v21h30V41h79v51h-31v48h-62v-28h-45v32h-47v-29H85v22H47Z" fill="none" stroke="#e8cb73" stroke-width="6"/><path d="M41 84h12m-12 6h12" stroke="#fb6848" stroke-width="5"/><rect x="39" y="79" width="4" height="4" fill="#fff1c4"/><rect x="47" y="79" width="4" height="4" fill="#fff1c4"/></svg>`}
function resultTable(type){const qualifying=type==='qualifying',rows=qualifying?state.data.qualifyingResults:type==='sprint'?state.data.sprintResults:state.data.results;return `<div class="table-scroll"><table class="timing-table results-table"><caption class="sr-only">${qualifying?'Singapore qualifying':type==='sprint'?'Singapore Sprint':'Latest Grand Prix'} classification</caption><thead><tr><th>POS</th><th>DRIVER</th>${qualifying?'<th class="desktop-cell">Q1</th><th class="desktop-cell">Q2</th><th>Q3 / BEST</th>':'<th>TIME / STATUS</th><th class="score">PTS</th>'}</tr></thead><tbody>${rows.map(r=>`<tr><td class="position ${Number(r.position)<=3?'podium':''}">${esc(String(r.position).padStart(2,'0'))}</td><td>${driverLink(find('driver',r.driverId),true)}${r.note?`<small class="result-note">${esc(r.note)}</small>`:''}</td>${qualifying?`<td class="desktop-cell lap-time">${esc(r.q1||'—')}</td><td class="desktop-cell lap-time">${esc(r.q2||'—')}</td><td class="lap-time best-time">${esc(r.q3||r.q2||r.q1||'NO TIME')}</td>`:`<td class="lap-time">${esc(r.time||r.status||'—')}</td><td class="score"><b>${n(r.points)}</b></td>`}</tr>`).join('')}</tbody></table></div>`}
function racePage(id){const current=id==='singapore',race=current?state.data.calendar.find(r=>r.round===17):state.data.calendar.find(r=>String(r.round)===id);if(!race)return notFound();if(!current)return `<a class="back-link" href="#/races">← RACE CALENDAR</a>${heading('ROUND '+String(race.round).padStart(2,'0'),esc(race.name),race.circuit)}<section class="panel race-file"><div class="race-file-art">${circuitGraphic()}<span>ARCADE CIRCUIT MOTIF · NOT A TRACK MAP</span></div><div><span class="section-kicker">RACE FILE / ${esc(race.country)}</span><h2>${esc(race.location||race.country)}</h2>${stats([[date(race.date),'DATE / UTC'],[race.time?.slice(0,5)||'TBC','START / UTC']])}<p>${race.status==='completed'?'Race date has passed. Follow the official event page for complete results.':'Race schedule is based on the saved calendar and may change.'}${race.localRaceDate!==race.date?' Local race date: '+date(race.localRaceDate)+'.':''}</p>${ext(race.url,'OFFICIAL EVENT','button primary')}</div></section>${race.round===state.data.lastRace?.round?`<section class="panel">${sectionHead('LAST GRAND PRIX','Race classification')}${resultTable('race')}${stamp('results')}</section>`:''}${stamp('calendar')}`;
return `<a class="back-link" href="#/races">← RACE CALENDAR</a>${heading('RACE CENTRE / ROUND 17','SINGAPORE <em>GRAND PRIX.</em>','Marina Bay Street Circuit · 9—11 October 2026')}<div class="race-centre-top"><section class="circuit-scene" style="--scene:url('${esc(window.PADDOCK_ART.scene)}')"><span class="pixel-tag">UNDER THE LIGHTS</span><div><span>RACE WINNER / 11 OCTOBER</span><h2>MAX VERSTAPPEN</h2><p>62 LAPS · 1:42:00.785</p></div></section><section class="panel">${sectionHead('WEEKEND SCHEDULE','Every session')}${sessions()}</section></div><section class="panel race-classification">${sectionHead('TIMING SCREEN','Session classification',`<div class="tabs">${tabButton('RACE','race',state.session==='race','data-session')}${tabButton('QUALIFYING','qualifying',state.session==='qualifying','data-session')}${tabButton('SPRINT','sprint',state.session==='sprint','data-session')}</div>`)}<div class="panel-context" id="session-context">${state.session==='qualifying'?'QUALIFYING ORDER · GRID PENALTIES MAY APPLY':state.session==='sprint'?'SPRINT CLASSIFICATION · POINTS AWARDED':'GRAND PRIX CLASSIFICATION · 11 OCTOBER 2026'}</div><div id="session-results">${resultTable(state.session)}</div><div class="panel-foot">${ext(state.data.meta.sectionFreshness[state.session==='qualifying'?'qualifyingResults':state.session==='sprint'?'sprintResults':'results'].sourceUrls[0],'OFFICIAL CLASSIFICATION')}<span id="session-date">${state.session==='race'?'11':'10'} OCTOBER 2026</span></div></section><div class="notice">RACE COMPLETE. Official classification checked on 12 October 2026. Choose a session to compare the race, qualifying and Sprint.</div><section class="news-section">${sectionHead('ROUND 17','Weekend dispatches')}<div class="news-grid">${state.data.news.slice(0,6).map(newsCard).join('')}</div></section>${stamp('results')}`}
function calendarPage(){return `${heading('05 / WORLD TOUR','THE ROAD <em>TO ABU DHABI.</em>','23 rounds. One world championship. Dates and times below are UTC.')}<a class="calendar-feature" href="#/race/singapore" style="--scene:url('${esc(window.PADDOCK_ART.scene)}')"><div><span class="pixel-tag">LATEST RACE / ROUND 17</span><h2>SINGAPORE<br><em>11 OCTOBER.</em></h2><p>RACE + SPRINT + QUALIFYING RESULTS</p></div><span class="button primary">OPEN RACE CENTRE →</span></a><div class="calendar-grid">${state.data.calendar.map(r=>`<article class="calendar-card ${r.round===17?'current':''} ${r.status==='completed'?'completed':''}"><div class="calendar-top"><span>ROUND ${String(r.round).padStart(2,'0')}</span><span>${r.round===17?'LATEST':r.status==='completed'?'COMPLETE':'UPCOMING'}</span></div><span class="calendar-country">${esc(r.country)}</span><h2><a href="#/race/${r.round===17?'singapore':r.round}">${esc(r.name.replace(' Grand Prix',''))}</a></h2><p>${esc(r.circuit)}</p><div class="calendar-bottom"><time datetime="${esc(r.date)}">${date(r.date)} <small>${r.time?.slice(0,5)||'TBC'} UTC</small></time><a href="#/race/${r.round===17?'singapore':r.round}" aria-label="Open ${esc(r.name)}">→</a></div>${r.localRaceDate!==r.date?`<small class="local-date">LOCAL DATE ${date(r.localRaceDate)}</small>`:''}</article>`).join('')}</div>${stamp('calendar')}`}
function commentCard(c){return `<article class="comment-card"><div class="comment-author"><span class="pixel-avatar">${esc(c.author.slice(0,2).toUpperCase())}</span><div><strong>u/${esc(c.author)}</strong><small>${esc(c.dateLabel||'Sourced fan comment')} · ${date(c.contextDate)}</small></div><span>FAN RADIO</span></div><blockquote>${esc(c.text)}</blockquote><div class="comment-bottom"><div class="tags">${(c.tags||[]).slice(0,3).map(tagLink).join('')}</div>${ext(c.url,'ORIGINAL COMMENT')}</div></article>`}
function notesMarkup(){return `<section class="panel notebook">${sectionHead('YOUR SAVE FILE','Private race notes')}<p>Only in this browser. Nothing is posted publicly.</p><form id="note-form"><label class="sr-only" for="note-text">Your private race note</label><textarea id="note-text" name="text" maxlength="1000" placeholder="A prediction, a hot take, a reminder…" required></textarea><button class="button primary" type="submit">SAVE NOTE +</button></form><div id="notes-list">${noteList()}</div></section>`}
function noteList(){return state.notes.length?[...state.notes].reverse().map(note=>`<article class="private-note"><div><small>${date(note.createdAt)}</small><button data-delete-note="${esc(note.id)}" aria-label="Delete note">×</button></div><p>${esc(note.text)}</p></article>`).join(''):'<p class="no-notes">Your notebook is empty. Start a new lap.</p>'}
function paddockPage(){return `${heading('06 / PADDOCK RADIO','OFF TRACK.<br><em>ON THE RADIO.</em>','Linked reporting, sourced fan conversations and your private race notebook.')}<div class="paddock-tabs"><div class="tabs">${tabButton('NEWS WIRE','news',state.paddockTab==='news','data-paddock-tab')}${tabButton('FAN RADIO','comments',state.paddockTab==='comments','data-paddock-tab')}${tabButton('MY NOTES','notes',state.paddockTab==='notes','data-paddock-tab')}</div><span class="wire-label"><i class="status-dot"></i> SOURCED SNAPSHOT</span></div>${state.paddockTab==='notes'?notesMarkup():`<div class="filter-bar"><label class="search-field"><span aria-hidden="true">⌕</span><span class="sr-only">Search the paddock</span><input id="search" type="search" value="${esc(state.search)}" placeholder="SEARCH THE RADIO…"></label><select id="entity-filter" aria-label="Filter news or comments"><option value="">EVERYONE</option>${[...state.data.teams,...state.data.drivers,...state.data.principals].map(e=>`<option value="${esc(e.id)}" ${state.newsEntity===e.id?'selected':''}>${esc(e.name)}</option>`).join('')}</select><span id="result-count"></span></div>${state.paddockTab==='comments'?'<div class="notice">Direct quotes from public Reddit discussions. Fan opinions belong to their authors; context dates are shown because exact publication times were not exposed.</div>':''}<div id="paddock-results" class="${state.paddockTab==='news'?'news-grid':'comments-grid'}"></div>${stamp(state.paddockTab==='news'?'news':'comments')}`}`}
function updatePaddock(){if(state.paddockTab==='notes')return;const key=state.paddockTab==='news'?'news':'comments',items=state.data[key].filter(x=>(!state.newsEntity||(x.tags||[]).includes(state.newsEntity))&&(!state.search||[x.title,x.summary,x.text,x.author].join(' ').toLowerCase().includes(state.search.toLowerCase())));$('#paddock-results').innerHTML=items.length?items.map(key==='news'?newsCard:commentCard).join(''):empty('NO SIGNAL HERE','Try a different name, team or search.');$('#result-count').textContent=items.length+' '+(key==='news'?'STORIES':'COMMENTS')}
function favoritesPage(){const items=state.favorites.map(k=>{const[kind,id]=k.split(':');return {kind,item:['driver','team','principal'].includes(kind)?find(kind,id):null}}).filter(x=>x.item);return `${heading('YOUR SAVE FILE','MY <em>GRID.</em>','Your saved drivers, garages and pit-wall personalities.')}<div class="saved-grid">${items.length?items.map(({kind,item})=>kind==='team'?teamCard(item,state.data.teams.indexOf(item)):kind==='principal'?leaderCard(item):`<article class="saved-driver" style="--team:${col(teamOf(item)?.color)}">${fav(kind,item)}${sprite(item)}<h2><a href="${path(kind,item.id)}">${esc(item.name)}</a></h2><p>${esc(teamOf(item)?.name)}</p><a class="button secondary" href="${path(kind,item.id)}">OPEN PROFILE →</a></article>`).join(''):empty('YOUR GRID IS OPEN','Tap the heart on a driver, team or principal to keep them here.')}</div>`}
function sourcesPage(){return `${heading('DATA / SOURCE LOG','KNOW <em>THE SNAPSHOT.</em>','Real source records, with the session and retrieval time kept separate.')}<section class="source-summary panel"><div><span class="section-kicker">CURRENT CAPTURE</span><h2>${date(state.data.meta.updatedAt,true)}</h2><p>${time(state.data.meta.updatedAt)} · after the Singapore Grand Prix.</p></div><div><span class="section-kicker">COVERAGE</span><p>22 current drivers · 23 classified season drivers<br>11 teams · 13 leadership profiles · 23 rounds</p></div><button class="button secondary" id="refresh-data">↻ RELOAD SNAPSHOT</button></section><div class="notice">Reload retrieves the website’s latest saved data file. This dashboard does not claim live timing. Exact publication dates are shown only where the source provides them.</div><div class="source-ledger">${Object.entries(state.data.meta.sectionFreshness).map(([key,x])=>`<section class="source-record"><div><span class="section-kicker">${esc(key.replace(/([A-Z])/g,' $1').toUpperCase())}</span><h2>${esc(x.session||'Reviewed source records')}</h2><p>${esc(x.note||'Verified against the linked source.')}</p><div class="source-times"><span>CHECKED <b>${date(x.fetchedAt)} · ${time(x.fetchedAt)}</b></span><span>PUBLISHED <b>${x.sourcePublishedAt?date(x.sourcePublishedAt,true):'Not exposed by source'}</b></span></div></div><div class="source-links">${x.sourceUrls.map((u,i)=>ext(u,(new URL(u).hostname.replace('www.',''))+(x.sourceUrls.length>1?' / '+(i+1):''))).join('')}</div></section>`).join('')}</div><section class="panel source-art-notes"><h2>ART & INTERPRETATION</h2><p>Pixel illustrations and signature animations are original fan interpretations. They are not official portraits, endorsements, or measurements of the current cars. The circuit motif on archived race files is decorative.</p></section>`}
function notFound(){return `<div class="empty-state not-found"><span>404 / WRONG GARAGE</span><h1>THIS TRACK<br>ENDS HERE.</h1><p>That page is not in the current cartridge.</p><a class="button primary" href="#/">RETURN TO RACE CONTROL →</a></div>`}
function render(focus=false){if(!state.data)return;const r=route();let page=r.page;if(page==='news'){page='paddock';state.paddockTab='news'}if(page==='calendar')page='races';const nav=({driver:'drivers',team:'teams',principal:'principals',race:'races'})[page]||page;$$('[data-nav]').forEach(a=>{const on=a.dataset.nav===nav;a.classList.toggle('active',on);on?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current')});main.innerHTML=page==='dashboard'?home():page==='drivers'?driverPage():page==='teams'?teamsPage():page==='principals'?leadersPage():['driver','team','principal'].includes(page)?profile(page,r.id):page==='races'?calendarPage():page==='race'?racePage(r.id):page==='paddock'?paddockPage():page==='favorites'?favoritesPage():page==='sources'?sourcesPage():notFound();document.title=(['driver','team','principal'].includes(page)?find(page,r.id)?.name:({dashboard:'Race Control',drivers:'Driver Select',teams:'The Garages',principals:'The Pit Wall',races:'Race Calendar',race:'Race Centre',paddock:'Paddock Radio',sources:'Source Log',favorites:'My Grid'})[page]||'Wrong Garage')+' · Pixel Paddock';if(page==='paddock')updatePaddock();updateCount();updateClock();if(focus){window.scrollTo(0,0);main.focus({preventScroll:true})}}
function updateCount(){$('#favorite-count').textContent=state.favorites.length}
function updateMotion(){const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;document.body.classList.toggle('motion-off',!state.motion||reduced);$('#motion-toggle').textContent=!state.motion||reduced?'FX OFF':'FX ON';$('#motion-toggle').setAttribute('aria-pressed',String(state.motion&&!reduced))}
function updateClock(){$$('[data-countdown]').forEach(el=>{const seconds=Math.max(0,Math.floor((Date.parse(el.dataset.countdown)-Date.now())/1000)),v={d:Math.floor(seconds/86400),h:Math.floor(seconds/3600)%24,m:Math.floor(seconds/60)%60,s:seconds%60};Object.entries(v).forEach(([k,x])=>{const n=$(`[data-unit="${k}"]`,el);if(n)n.textContent=String(x).padStart(2,'0')});if(!seconds)el.setAttribute('aria-label','Scheduled race start reached; results require a newer source snapshot')})}
async function load(refresh=false){try{let data;if(window.PIXEL_PADDOCK_BOOTSTRAP)data=window.PIXEL_PADDOCK_BOOTSTRAP;else{const r=await fetch('data/content.json'+(refresh?'?t='+Date.now():''),{cache:'no-store'});if(!r.ok)throw Error('Data response '+r.status);data=await r.json()}if(!data?.drivers?.length||!data.currentWeekend||!data.meta.sectionFreshness)throw Error('Incomplete source snapshot');state.data=data;$('#snapshot-label').textContent='SOURCE SNAPSHOT / '+date(data.meta.updatedAt).toUpperCase()+' '+time(data.meta.updatedAt);render();if(refresh)toast(window.PIXEL_PADDOCK_BOOTSTRAP?'Offline cartridge reloaded. Capture date is unchanged.':'Saved source snapshot reloaded. Check its date for freshness.')}catch(e){main.innerHTML=`<div class="empty-state"><h1>CARTRIDGE NOT READY</h1><p>The saved racing data could not be loaded.</p><button id="refresh-data" class="button primary">TRY AGAIN ↻</button></div>`;console.error(e)}}
function updateDriverSearch(){const list=filteredDrivers();if(list.length&&!list.some(x=>x.id===state.selectedDriver)){state.selectedDriver=list[0].id;$('#driver-preview').innerHTML=driverPreview()}$('#driver-slots').innerHTML=list.length?list.map(driverSlot).join(''):empty('NO DRIVER FOUND','Try another name, number or team.')}
function closeMenu(){$('#main-nav').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false')}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.id==='menu-toggle'){const open=$('#main-nav').classList.toggle('open');b.setAttribute('aria-expanded',String(open));return}if(b.closest('.main-nav'))closeMenu();if(b.id==='motion-toggle'){state.motion=!state.motion;save('motion',state.motion);updateMotion();return}if(b.id==='refresh-data'){load(true);return}if(b.dataset.selectDriver){state.selectedDriver=b.dataset.selectDriver;$('#driver-preview').innerHTML=driverPreview();$$('[data-select-driver]').forEach(x=>{const on=x.dataset.selectDriver===state.selectedDriver;x.setAttribute('aria-pressed',String(on));x.closest('.driver-slot').classList.toggle('selected',on)});return}if(b.dataset.play){if(document.body.classList.contains('motion-off')){toast('Motion is off. Enable FX to play the signature.');return}const id=b.dataset.play;$$('[data-person]').filter(x=>x.dataset.person===id).forEach(x=>{x.classList.remove('playing');void x.offsetWidth;x.classList.add('playing');clearTimeout(x._timer);x._timer=setTimeout(()=>x.classList.remove('playing'),3600)});return}if(b.dataset.favorite){const k=b.dataset.favorite,on=state.favorites.includes(k);state.favorites=on?state.favorites.filter(x=>x!==k):[...state.favorites,k];save('favorites',state.favorites);updateCount();$$('[data-favorite]').filter(x=>x.dataset.favorite===k).forEach(x=>{x.classList.toggle('saved',!on);x.setAttribute('aria-pressed',String(!on));x.textContent=(on?'♡':'♥')+(x.classList.contains('button')?on?' SAVE TO MY GRID':' SAVED':'')});if(route().page==='favorites')render();toast(on?'Removed from your grid.':'Saved to your grid.');return}if(b.dataset.table){state.table=b.dataset.table;$$('[data-table]').forEach(x=>{x.classList.toggle('active',x.dataset.table===state.table);x.setAttribute('aria-pressed',String(x.dataset.table===state.table))});$('#standings-table').innerHTML=standingsTable();return}if(b.hasAttribute('data-expand-standings')){state.fullStandings=!state.fullStandings;$('#standings-table').innerHTML=standingsTable();b.textContent=(state.fullStandings?'SHOW TOP SIX':'FULL CLASSIFICATION')+' ↓';return}if(b.dataset.session){state.session=b.dataset.session;$$('[data-session]').forEach(x=>{const on=x.dataset.session===state.session;x.classList.toggle('active',on);x.setAttribute('aria-pressed',String(on))});$('#session-results').innerHTML=resultTable(state.session);$('#session-context').textContent=state.session==='qualifying'?'QUALIFYING ORDER · GRID PENALTIES MAY APPLY':state.session==='sprint'?'SPRINT CLASSIFICATION · POINTS AWARDED':'GRAND PRIX CLASSIFICATION · 11 OCTOBER 2026';const link=$('.race-classification .panel-foot a');$('#session-date').textContent=(state.session==='race'?'11':'10')+' OCTOBER 2026';link.href=state.data.meta.sectionFreshness[state.session==='qualifying'?'qualifyingResults':state.session==='sprint'?'sprintResults':'results'].sourceUrls[0];return}if(b.dataset.paddockTab){state.paddockTab=b.dataset.paddockTab;state.search='';render();return}if(b.dataset.deleteNote){state.notes=state.notes.filter(x=>x.id!==b.dataset.deleteNote);save('notes',state.notes);$('#notes-list').innerHTML=noteList();toast('Private note deleted.')}});
document.addEventListener('input',e=>{if(e.target.id==='search'){state.search=e.target.value;if(route().page==='drivers')updateDriverSearch();else updatePaddock()}});
document.addEventListener('change',e=>{if(e.target.id==='team-filter'){state.team=e.target.value;updateDriverSearch()}if(e.target.id==='entity-filter'){state.newsEntity=e.target.value;updatePaddock()}});
document.addEventListener('submit',e=>{if(e.target.id!=='note-form')return;e.preventDefault();const text=e.target.elements.text.value.trim();if(!text)return;state.notes.push({id:Date.now().toString(36),text:text.slice(0,1000),createdAt:new Date().toISOString()});save('notes',state.notes);e.target.reset();$('#notes-list').innerHTML=noteList();toast('Private note saved in this browser.')});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();if(e.target.matches('[data-select-driver]')&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const buttons=$$('[data-select-driver]'),i=buttons.indexOf(e.target),columns=getComputedStyle($('#driver-slots')).gridTemplateColumns.split(' ').length,delta={ArrowLeft:-1,ArrowRight:1,ArrowUp:-columns,ArrowDown:columns}[e.key],next=buttons[(i+delta+buttons.length)%buttons.length];next.click();next.focus()}});
window.addEventListener('hashchange',()=>{state.search='';state.team='';state.newsEntity=route().params.get('entity')||'';closeMenu();render(true)});state.newsEntity=route().params.get('entity')||'';updateMotion();setInterval(updateClock,1000);load();
})();
